package solution

import (
	"errors"
	"sort"
)

var (
	ErrInvalidAsset  = errors.New("invalid asset")
	ErrAssetExists   = errors.New("asset already exists")
	ErrAssetNotFound = errors.New("asset not found")
)

type Asset struct {
	ID, Name, Zone string
	Tags           []string
}

type Inventory struct {
	items map[string]Asset
}

func NewInventory() *Inventory {
	return &Inventory{items: make(map[string]Asset)}
}

func validID(id string) bool {
	if id == "" || id[0] == '0' {
		return false
	}
	for index := 0; index < len(id); index++ {
		if id[index] < '0' || id[index] > '9' {
			return false
		}
	}
	return true
}

func validAsset(asset Asset) bool {
	if !validID(asset.ID) || asset.Name == "" || asset.Zone == "" {
		return false
	}
	for _, tag := range asset.Tags {
		if tag == "" {
			return false
		}
	}
	return true
}

func copyAsset(asset Asset) Asset {
	asset.Tags = append([]string(nil), asset.Tags...)
	return asset
}

func (i *Inventory) Add(asset Asset) error {
	if !validAsset(asset) {
		return ErrInvalidAsset
	}
	if _, exists := i.items[asset.ID]; exists {
		return ErrAssetExists
	}
	i.items[asset.ID] = copyAsset(asset)
	return nil
}

func (i *Inventory) Update(asset Asset) error {
	if !validAsset(asset) {
		return ErrInvalidAsset
	}
	if _, exists := i.items[asset.ID]; !exists {
		return ErrAssetNotFound
	}
	i.items[asset.ID] = copyAsset(asset)
	return nil
}

func (i *Inventory) Delete(id string) error {
	if _, exists := i.items[id]; !exists {
		return ErrAssetNotFound
	}
	delete(i.items, id)
	return nil
}

func (i *Inventory) Get(id string) (Asset, error) {
	asset, exists := i.items[id]
	if !exists {
		return Asset{}, ErrAssetNotFound
	}
	return copyAsset(asset), nil
}

func (i *Inventory) IDs() []string {
	ids := make([]string, 0, len(i.items))
	for id := range i.items {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

func (i *Inventory) Snapshot() map[string]Asset {
	snapshot := make(map[string]Asset, len(i.items))
	for id, asset := range i.items {
		snapshot[id] = copyAsset(asset)
	}
	return snapshot
}

func (i *Inventory) Clear() {
	i.items = make(map[string]Asset)
}
